<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch,nextTick} from 'vue'
import DialoguePortrait from './DialoguePortrait.vue'
import SceneCinema from './SceneCinema.vue'
import {buildChapters,complete,guideCandidates,shortName,selectSceneVideo,type Row,type Question} from './dialogueStory'
const props=defineProps<{project:Row}>(),emit=defineEmits<{close:[]}>()
const presentation=computed(()=>props.project.interaction?.presentation||{})
const paintingName=computed(()=>props.project.paintingInfo?.name||props.project.title||'古画')
const closing=computed(()=>presentation.value.closing||(paintingName.value.includes('折槛')?'殿上已散，只剩这段旧栏还在。往后再有人说起今日的事，总该记得，曾有人在这里直言。':'画中这一段故事已经读完。带着刚才听到的话，再回望画中人物。'))
type Phase='pick'|'intro'|'lead'|'explore'|'reply'|'unlock'|'film'|'done'
const selectedPerson=ref('')
const phase=ref<Phase>('pick'),guideId=ref(''),sceneIndex=ref(0),read=ref<string[]>([]),unlocked=ref<string[]>([]),introIndex=ref(0),replyId=ref(''),shown=ref(''),journal=ref(false),evidence=ref(false),jobs=ref<Row[]>([])
const paintHost=ref<HTMLElement|null>(null),imageBounds=ref({left:0,top:0,width:0,height:0})
let observer:ResizeObserver|undefined
function measurePainting(){const host=paintHost.value,im=host?.querySelector('img');if(!host||!im?.naturalWidth)return;const r=host.getBoundingClientRect(),scale=Math.min(r.width/im.naturalWidth,r.height/im.naturalHeight);const width=im.naturalWidth*scale,height=im.naturalHeight*scale;imageBounds.value={left:(r.width-width)/2,top:(r.height-height)/2,width,height}}
const nameplates=computed(()=>{const b=imageBounds.value,placed:{x:number;y:number;w:number}[]=[];return (props.project.annotations||[]).filter((a:Row)=>a.kind==='character'&&person(a.characterId)).map((a:Row)=>{const label=shortName(person(a.characterId)?.name||''),w=label.length*12+22+(phase.value==='explore'&&a.characterId===question.value?.personId?42:0),x=Math.min(b.width-w/2,Math.max(w/2,(a.x+a.w/2)*b.width));let y=Math.max(12,a.y*b.height-12);for(let n=0;n<8&&placed.some(p=>Math.abs(p.x-x)<(p.w+w)/2+4&&Math.abs(p.y-y)<28);n++)y=Math.max(10,y-28);placed.push({x,y,w});return {id:a.id,personId:a.characterId,label,style:{left:x+'px',top:y+'px'}}})})
function selectPerson(id:string){if(phase.value==='explore'&&question.value?.personId===id)selectedPerson.value=id}
let typer=0
let oldOverflow='',previousFocus:HTMLElement|null=null
const replayReturn=ref<{index:number;phase:Phase}|null>(null)
const chapters=computed(()=>buildChapters(props.project)),chapter=computed(()=>chapters.value[sceneIndex.value]),guides=computed(()=>guideCandidates(props.project)),people=computed<Row[]>(()=>props.project.characters||[])
const guideBox=computed(()=>guides.value.find((a:Row)=>a.id===guideId.value))
const person=(id:string)=>people.value.find(c=>c.id===id)
const guideName=computed(()=>shortName(person(guideBox.value?.characterId)?.name||'引路宫人'))
const question=computed(()=>chapter.value?.questions.find(q=>!read.value.includes(q.id)))
const reply=computed(()=>chapter.value?.questions.find(q=>q.id===replyId.value))
const cast=computed(()=>['pick','intro'].includes(phase.value)?[]:Array.from(new Map((chapter.value?.questions.filter(q=>read.value.includes(q.id)||q.id===question.value?.id)||[]).map(q=>[q.personId,q])).values()))
const intro=computed(()=>[`${paintingName.value.includes('折槛')?(person(guideBox.value?.characterId)?.name.startsWith('宫女')?'奴婢':'奴才')+guideName.value+'，给您请安。':'我是'+guideName.value+'，请随我一起看画。'}${chapter.value?.lead||''}`])
const followup=computed(()=>{const name=person(question.value?.personId||'')?.name||'这位大人';return name==='张禹'?'右边这位是安昌侯张禹，也曾教授天子经学。':name==='朱云'?'朱云仍朝着御座，似乎还有话要说。':`${name}也准备开口了，听听接下来这番话。`})
const fullText=computed(()=>phase.value==='intro'?intro.value[0]:phase.value==='reply'?reply.value?.answer||'':phase.value==='unlock'?chapter.value?.outro||'这一幕的线索，您已经听过了。':phase.value==='done'?closing.value:phase.value==='explore'?'':read.value.some(id=>id.startsWith(chapter.value.id+':'))?followup.value:chapter.value?.lead||'')
const speaker=computed(()=>phase.value==='reply'?person(reply.value?.personId||''):person(guideBox.value?.characterId))
const activeName=computed(()=>phase.value==='reply'?shortName(speaker.value?.name||'画中人'):guideName.value)
const portraitBox=computed(()=>phase.value==='reply'?(props.project.annotations||[]).find((a:Row)=>a.characterId===speaker.value?.id):guideBox.value)
const filmBoard=computed(()=>(props.project.storyboards||[]).find((b:Row)=>b.sceneId===chapter.value?.id))
const filmVideo=computed(()=>selectSceneVideo(props.project,jobs.value,chapter.value?.id)?.videoUrl||'')
const ready=computed(()=>shown.value===fullText.value)
const key=computed(()=>'animatedscroll-dialogue-v3:'+props.project.id)
const signature=computed(()=>JSON.stringify({guides:guides.value.map((g:Row)=>g.id),chapters:chapters.value}) )
function save(){localStorage.setItem(key.value,JSON.stringify({signature:signature.value,guideId:guideId.value,sceneIndex:sceneIndex.value,read:read.value,unlocked:unlocked.value,phase:phase.value,introIndex:introIndex.value,replyId:replyId.value,replayReturn:replayReturn.value}))}
function selectGuide(id:string){guideId.value=id}
function begin(){if(!guideBox.value&&guideId.value!=='voice')return;phase.value='intro';introIndex.value=0;save()}
function reset(){replayReturn.value=null;localStorage.removeItem(key.value);phase.value='pick';guideId.value=guides.value[0]?.id||'voice';sceneIndex.value=0;read.value=[];unlocked.value=[];introIndex.value=0;replyId.value='';journal.value=false;evidence.value=false}
function type(text:string){window.clearInterval(typer);if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){shown.value=text;return}shown.value='';let i=0;typer=window.setInterval(()=>{shown.value=text.slice(0,++i);if(i>=text.length)window.clearInterval(typer)},24)}
function finish(){window.clearInterval(typer);shown.value=fullText.value}
function next(){
 if(!ready.value){finish();return}
 if(phase.value==='intro'){if(introIndex.value<intro.value.length-1)introIndex.value++;else{phase.value=chapter.value?.questions.length?'explore':'done';selectedPerson.value=''}}
 else if(phase.value==='lead'){phase.value='explore';selectedPerson.value=''}
 else if(phase.value==='reply'){
  if(reply.value&&!read.value.includes(reply.value.id))read.value.push(reply.value.id)
  if(complete(chapter.value,read.value)){if(!unlocked.value.includes(chapter.value.id))unlocked.value.push(chapter.value.id);phase.value='unlock'}else phase.value='lead'
 }else if(phase.value==='unlock')phase.value='film'
 save()
}
function ask(q:Question){if(q.id!==question.value?.id||phase.value!=='explore')return;replyId.value=q.id;evidence.value=false;phase.value='reply';save()}
function closeFilm(){if(replayReturn.value){sceneIndex.value=replayReturn.value.index;phase.value=replayReturn.value.phase;replayReturn.value=null}else if(sceneIndex.value<chapters.value.length-1){sceneIndex.value++;phase.value=complete(chapter.value,read.value)?'unlock':'lead'}else phase.value='done';save()}
function replay(index:number){if(!unlocked.value.includes(chapters.value[index].id))return;replayReturn.value={index:sceneIndex.value,phase:phase.value};sceneIndex.value=index;phase.value='film';journal.value=false;save()}
function pin(a:Row){return {left:(a.x+a.w/2)*100+'%',top:(a.y+a.h*.16)*100+'%'}}
function escape(e:KeyboardEvent){if(e.key==='Tab'){const items=Array.from(document.querySelectorAll<HTMLElement>('.vn button:not(:disabled),.vn video[controls],.vn summary')).filter(el=>el.getClientRects().length>0);const first=items[0],last=items[items.length-1];if(first&&(!document.querySelector('.vn')?.contains(document.activeElement)||e.shiftKey&&document.activeElement===first||!e.shiftKey&&document.activeElement===last)){e.preventDefault();(e.shiftKey?last:first).focus()}}if(e.key==='Escape'){if(journal.value)journal.value=false;else emit('close')}if(e.code==='Space'&&!journal.value&&['intro','lead','reply','unlock'].includes(phase.value)&&!(e.target instanceof HTMLInputElement)&&!(e.target instanceof HTMLButtonElement)){e.preventDefault();next()}}
watch(fullText,t=>type(t),{immediate:true})
watch(phase,async()=>{await nextTick();observer?.disconnect();if(paintHost.value){observer=new ResizeObserver(measurePainting);observer.observe(paintHost.value);measurePainting()}},{flush:'post'})
onMounted(async()=>{
 oldOverflow=document.body.style.overflow;document.body.style.overflow='hidden';previousFocus=document.activeElement as HTMLElement
 guideId.value=guides.value[0]?.id||'voice'
 try{const saved=JSON.parse(localStorage.getItem(key.value)||'null');if(saved?.signature===signature.value){const valid=new Set(chapters.value.flatMap(c=>c.questions.map(q=>q.id)));read.value=(saved.read||[]).filter((id:string)=>valid.has(id));unlocked.value=chapters.value.filter(c=>complete(c,read.value)).map(c=>c.id);sceneIndex.value=Math.max(0,Math.min(saved.sceneIndex||0,chapters.value.length-1));if(saved.guideId==='voice'||guides.value.some((g:Row)=>g.id===saved.guideId))guideId.value=saved.guideId;introIndex.value=Math.min(saved.introIndex||0,1);replyId.value=saved.replyId||'';if(saved.replayReturn&&saved.replayReturn.index>=0&&saved.replayReturn.index<chapters.value.length)replayReturn.value=saved.replayReturn;const allowed:Phase[]=['pick','intro','lead','explore','reply','unlock','film','done'];phase.value=allowed.includes(saved.phase)?saved.phase:'pick';if(['film','unlock'].includes(phase.value)&&!unlocked.value.includes(chapter.value.id))phase.value='lead';if(phase.value==='done'&&unlocked.value.length!==chapters.value.length)phase.value='lead'}}catch{reset()}
 document.addEventListener('keydown',escape)
 try{const r=await fetch('/api/projects/'+props.project.id+'/videos');if(r.ok)jobs.value=(await r.json()).jobs||[]}catch{}
})
onUnmounted(()=>{observer?.disconnect();window.clearInterval(typer);document.removeEventListener('keydown',escape);document.body.style.overflow=oldOverflow;previousFocus?.focus()})
</script>

<template>
<div class="vn" role="dialog" aria-modal="true" aria-label="入画对话">
 <header class="vn-top"><button class="back" @click="emit('close')">← 返回创作</button><div class="vn-brand"><span>INTO THE PAINTING</span><h1>画中有话</h1></div><div class="top-actions"><button @click="journal=!journal">线索手记 <b>{{read.length}}</b></button><button class="restart" @click="reset">重新入画</button></div></header>
 <section v-if="phase==='pick'" class="guide-picker">
  <div class="pick-copy"><span class="eyebrow">{{presentation.kicker||paintingName+' · 入画对话'}}</span><h2 class="presentation-lines">{{presentation.headline||'借一双画中人的眼睛，\n走近这幅画的故事。'}}</h2><p class="presentation-lines">{{presentation.description||'从一位画中人的讲述开始。\n听线索，再向相关人物提问。'}}</p>
   <div class="guide-list"><button v-for="a in guides" :key="a.id" class="guide-card" :class="{chosen:guideId===a.id}" :aria-pressed="guideId===a.id" @click="selectGuide(a.id)"><div class="guide-crop"><DialoguePortrait :url="project.image" :box="a" :label="person(a.characterId)?.name||'引路人'"/></div><div><small>画中引路人</small><strong>{{shortName(person(a.characterId)?.name||'宫人')}}</strong><span>随画中人物，串起线索</span></div><b class="pick-check">{{guideId===a.id?'✓':'○'}}</b></button></div>
   <button v-if="guides.length" class="enter" @click="begin">随{{guideName}}入画 <span>→</span></button><button v-else class="enter" @click="guideId='voice';begin()">听引路人讲述，进入故事 →</button><small class="pick-foot">原画裁切形象 · {{chapters.length}} 幕故事 · 问答解锁场景</small>
  </div>
  <div class="pick-paint"><div class="painting-mat"><div class="painting-image"><img :src="project.image" :alt="paintingName+'，选择一位画中人物作为引路人'"><button v-for="a in guides" :key="a.id" class="guide-pin" :class="{selected:guideId===a.id}" :style="pin(a)" :aria-label="'选择'+person(a.characterId)?.name+'作引路人'" @click="selectGuide(a.id)"><i></i>{{shortName(person(a.characterId)?.name||'宫人')}}</button></div></div><div class="painting-caption"><span>{{paintingName}}</span><span>{{presentation.caption||'一幅古画 · 几种声音'}}</span></div></div>
 </section>
 <section v-else class="story-stage" :class="{cinema:phase==='film'}">
  <div v-if="phase!=='film'" class="story-art"><div class="scene-heading"><small>第 {{String(sceneIndex+1).padStart(2,'0')}} 幕 / {{String(chapters.length).padStart(2,'0')}}</small><h2>{{chapter?.title}}</h2><span>已听取 {{chapter?.questions.filter(q=>read.includes(q.id)).length||0}} / {{chapter?.questions.length||0}} 条线索</span></div><div ref="paintHost" class="scene-painting"><img :src="project.image" alt="当前故事发生的原幅古画" @load="measurePainting"><div v-if="imageBounds.width>0" class="person-pins" :style="{left:imageBounds.left+'px',top:imageBounds.top+'px',width:imageBounds.width+'px',height:imageBounds.height+'px'}"><button v-for="pin in nameplates" :key="pin.id" class="person-pin" :class="{available:phase==='explore'&&pin.personId===question?.personId,chosen:selectedPerson===pin.personId}" :style="pin.style" :disabled="phase!=='explore'||pin.personId!==question?.personId" :aria-label="'与'+pin.label+'对话'" @click="selectPerson(pin.personId)">{{pin.label}}<i v-if="phase==='explore'&&pin.personId===question?.personId">· 可交谈</i></button></div><span v-if="phase==='reply'" class="speaking-location">正在听 {{activeName}} 讲述</span></div><span class="art-caption">原画形象 · 演绎对话</span></div>
  <aside v-if="phase!=='film'" class="story-rail"><small class="eyebrow">循声入画</small><ol><li v-for="(c,i) in chapters" :key="c.id" :class="{current:i===sceneIndex,opened:unlocked.includes(c.id)}"><button :disabled="!unlocked.includes(c.id)" @click="replay(i)"><span>{{unlocked.includes(c.id)?'✓':String(i+1).padStart(2,'0')}}</span><div><b>{{i<=sceneIndex||unlocked.includes(c.id)?c.title:'尚未抵达的故事'}}</b><small>{{unlocked.includes(c.id)?'已解锁 · 回看':i===sceneIndex?'正在探问':'等待前一幕的线索'}}</small></div></button></li></ol><div class="cast-note"><small>此刻提到的人</small><span v-for="q in cast" :key="q.id" :class="{active:q.id===question?.id}">{{shortName(person(q.personId)?.name||'画中人')}} <b>{{read.includes(q.id)?'已听过':'可询问'}}</b></span></div></aside>
  <div class="dialogue-desk" v-if="phase!=='film'"><div v-if="portraitBox" class="portrait-platform"><DialoguePortrait :url="project.image" :box="portraitBox" :label="activeName+'的原画立绘'" soft/><div class="portrait-seal">{{activeName}}</div></div><div class="speech-panel"><div v-if="phase!=='explore'" class="speaker-label"><span>{{activeName}}</span><small>{{phase==='reply'?'画中人':'引路人'}}</small></div><button v-if="phase!=='explore'" class="speech-text" @click="next" :aria-label="ready?'继续对话':'显示完整对白'"><p aria-live="polite">{{shown}}<i v-if="!ready" class="type-cursor"></i></p></button><p v-if="phase==='explore'" class="explore-note">{{selectedPerson?'想问什么？':'画中已提及的人物可以交谈。'}}</p><div class="speech-foot"><button v-if="phase==='reply'&&reply?.quote" @click="evidence=!evidence">{{evidence?'收起依据':'原文依据 ↗'}}</button></div><div v-if="evidence&&reply" class="quote-note"><small>{{reply.sourceTitle}}</small>{{reply.quote}}</div></div>
   <div class="question-panel"><small>{{phase==='explore'?'你想问……':phase==='unlock'?'这一幕的线索已齐':phase==='done'?'画外，余音未散':'细听其言'}}</small><button v-if="phase==='explore'&&question&&selectedPerson===question.personId" class="question-choice" :disabled="!ready" @click="ask(question)"><span>{{question.question}}</span><b>问 {{shortName(person(question.personId)?.name||'当事人')}} →</b></button><button v-else-if="phase==='explore'" class="question-choice" @click="selectedPerson=question?.personId||''">选择画中已提及的人物</button><button v-else-if="phase==='done'" class="question-choice" @click="journal=true">打开线索手记 →</button><button v-else class="continue" @click="next">{{!ready?'读完这段话':phase==='unlock'?'观看本幕分镜 →':phase==='reply'?'继续 →':phase==='intro'||phase==='lead'?'了解了':'继续 →'}}</button><span class="quiet-hint">{{phase==='explore'?'点击画中姓名，与人物对话':'点击读完 · 空格继续'}}</span></div>
  </div>
  <SceneCinema v-if="phase==='film'" :title="chapter?.title||''" :outro="chapter?.outro||''" :index="sceneIndex" :total="chapters.length" :video-url="filmVideo" :image="project.image" :clues="chapter?.questions.map(q=>q.clue)||[]" :shots="filmBoard?.shots||[]" :replaying="!!replayReturn" @continue="closeFilm"/>
 </section>
 <div v-if="journal" class="journal-backdrop" @click.self="journal=false"><aside class="journal"><div><small>YOUR FIELD NOTES</small><button aria-label="关闭线索手记" @click="journal=false">×</button></div><h2>线索手记</h2><p>听过的话，留在这里。</p><template v-for="c in chapters" :key="c.id"><section v-if="c.questions.some(q=>read.includes(q.id))"><h3>{{c.title}}</h3><p v-for="q in c.questions.filter(q=>read.includes(q.id))" :key="q.id"><b>{{shortName(person(q.personId)?.name||'画中人')}}</b>{{q.clue}}</p><button v-if="unlocked.includes(c.id)" @click="replay(chapters.indexOf(c))">回看本幕场景 ↗</button></section></template><p v-if="!read.length" class="journal-empty">第一条线索，等你开口去问。</p></aside></div>
</div>
</template>

<style scoped>
.presentation-lines{white-space:pre-line}

